package com.bank.fees;

import java.math.BigDecimal;
import java.math.RoundingMode;

// Single responsibility: ONLY computes the transfer fee.
public class TransferFeeStrategy implements FeeStrategy {

    @Override
    public BigDecimal fee(BigDecimal amount) {
        // 0.1% fee, money in BigDecimal, rounded to 2 decimals.
        return amount.multiply(new BigDecimal("0.001"))
                     .setScale(2, RoundingMode.HALF_UP);
    }

    @Override
    public String type() { return "TRANSFER"; }
}
