package com.bank.fees;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class WithdrawalFeeStrategy implements FeeStrategy {

    @Override
    public BigDecimal fee(BigDecimal amount) {
        // Flat 20 rupees for withdrawals up to 10000, else 0.05%.
        if (amount.compareTo(new BigDecimal("10000")) <= 0) {
            return new BigDecimal("20.00");
        }
        return amount.multiply(new BigDecimal("0.0005"))
                     .setScale(2, RoundingMode.HALF_UP);
    }

    @Override
    public String type() { return "WITHDRAWAL"; }
}
