package com.bank.fees;

import java.math.BigDecimal;
import java.util.Map;
import java.util.stream.Collectors;

// Orchestrator: picks the right strategy. Loosely coupled via the interface,
// so it is trivially unit-testable and new fee types plug in cleanly.
public class FeeCalculator {

    private final Map<String, FeeStrategy> strategies;

    public FeeCalculator(java.util.List<FeeStrategy> strategyList) {
        // Build a lookup by type — dependency injected, not hardcoded.
        this.strategies = strategyList.stream()
                .collect(Collectors.toMap(FeeStrategy::type, s -> s));
    }

    public BigDecimal calculate(String type, BigDecimal amount) {
        if (amount == null || amount.signum() <= 0) {
            throw new IllegalArgumentException("amount must be positive");
        }
        FeeStrategy strategy = strategies.get(type);
        if (strategy == null) {
            throw new IllegalArgumentException("unknown fee type: " + type);
        }
        return strategy.fee(amount);
    }
}
