package com.bank.fees;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;

// TDD: these were written FIRST, before the calculator, to define the contract.
class FeeCalculatorTest {

    private final FeeCalculator calc = new FeeCalculator(
            List.of(new TransferFeeStrategy(), new WithdrawalFeeStrategy()));

    @Test
    void transferFeeIsTenthOfPercent() {
        // Rajesh transfers 100000 -> fee 100.00
        assertEquals(new BigDecimal("100.00"), calc.calculate("TRANSFER", new BigDecimal("100000")));
    }

    @Test
    void smallWithdrawalIsFlatFee() {
        assertEquals(new BigDecimal("20.00"), calc.calculate("WITHDRAWAL", new BigDecimal("5000")));
    }

    @Test
    void unknownTypeRejected() {
        assertThrows(IllegalArgumentException.class,
                () -> calc.calculate("MYSTERY", new BigDecimal("100")));
    }
}
